add_filter( 'sgo_css_combine_exclude', function ( $ex ) {
	$ex[] = 'dwdr';
	return $ex;
} );
add_filter( 'sgo_js_minify_exclude', function ( $ex ) {
	$ex[] = 'dwdr';
	return $ex;
} );

/**
 * wp_head for these pages, minus every other stylesheet and inline style (theme, Elementor, the old page
 * styles) and the old font/hero preloads. SEO tags, schema and tracking stay.
 */
function dwdr_head() {
	ob_start();
	wp_head();
	$h = (string) ob_get_clean();
	$keep_style = '/id=["\'](dwdr|admin-bar|dashicons|query-monitor)/';
	$h = preg_replace_callback( '#<link\b[^>]*rel=["\']stylesheet["\'][^>]*>\s*#i', function ( $m ) use ( $keep_style ) {
		return preg_match( $keep_style, $m[0] ) ? $m[0] : '';
	}, $h );
	$h = preg_replace_callback( '#<style\b[^>]*>.*?</style>\s*#is', function ( $m ) use ( $keep_style ) {
		return preg_match( $keep_style, $m[0] ) || false !== strpos( $m[0], 'img:is(' ) ? $m[0] : '';
	}, $h );
	$h = preg_replace( '#<link\b[^>]*rel=["\']preload["\'][^>]*>\s*#i', '', $h );
	$h = preg_replace( '#<link\b[^>]*fonts\.(googleapis|gstatic)\.com[^>]*>\s*#i', '', $h );
	echo '<link rel="preload" href="' . esc_url( DWDP_URL . 'assets/fonts/archivo-latin.woff2' ) . '" as="font" type="font/woff2" crossorigin>' . "\n";
	echo $h; // phpcs:ignore
}

/* ---------- Settings: the switch that makes it live ---------- */

add_action( 'admin_init', function () {
	register_setting( 'dwdr', 'dwdr_live', array( 'type' => 'string', 'sanitize_callback' => function ( $v ) { return '1' === (string) $v ? '1' : '0'; } ) );
} );
